#===- native_seh_bridge.s - Fixed x64 physical continuation experiment ---===#
#
# NeverD Decompiler
#
#===--------------------------------------------------------------------===#
# Own the native labels and unwind frame; call LLVM through ordinary ABI entries.
# No source-frame authority, reconstruction receipt, nesting or CET guarantee.
# Shadow space [0,32); source/observation cells [32,96); saved RBP at +96.
# The continuation descriptors at +48/+56 are generated by this trusted fixture.
.intel_syntax noprefix
.text
.globl neverd_native_seh_resume
.def neverd_native_seh_resume; .scl 2; .type 32; .endef
.seh_proc neverd_native_seh_resume
neverd_native_seh_resume:
  push rbp
  .seh_pushreg rbp
  sub rsp, 96
  .seh_stackalloc 96
  mov rbp, rsp
  .seh_setframe rbp, 0
  .seh_endprologue
  .seh_handler __C_specific_handler, @except, @unwind
  mov DWORD PTR [rsp+32], 1
  mov eax, ecx
  and eax, 1
  mov DWORD PTR [rsp+36], eax
  shr ecx, 1
  and ecx, 1
  mov DWORD PTR [rsp+64], ecx
  mov DWORD PTR [rsp+68], 0
  mov DWORD PTR [rsp+72], 0
  mov DWORD PTR [rsp+76], 0
  mov DWORD PTR [rsp+88], 0
  mov DWORD PTR [rsp+92], 0
  mov DWORD PTR [rsp+80], 0
  mov DWORD PTR [rsp+84], 0
  mov DWORD PTR [rsp+40], edx
  mov DWORD PTR [rsp+44], 1370025985
  lea rax, [rip+.Lresume_first]
  mov QWORD PTR [rsp+48], rax
  mov QWORD PTR [rsp+56], rsp
  cmp edx, 0
  je .Lnormal
.Ltry_begin:
  mov ecx, 0xe0424242
  xor edx, edx
  xor r8d, r8d
  xor r9d, r9d
  call QWORD PTR [rip+__imp_RaiseException]
  nop
.Ltry_end:
.Lnormal:
  mov DWORD PTR [rsp+32], 12
  xor ecx, ecx
  mov rdx, rsp
  call native_resume_cleanup
  nop
.Lnormal_call_end:
  mov rcx, rsp
  mov edx, 4
  call native_resume_step
  jmp .Lresume_first
.Lcatch_first:
  mov rcx, rsp
  mov edx, 6
  call native_resume_step
.Lresume_first:
  mov rcx, rsp
  mov edx, 7
  call native_resume_step
.Lsecond_begin:
  mov ecx, 0xe0424243
  xor edx, edx
  xor r8d, r8d
  xor r9d, r9d
  call QWORD PTR [rip+__imp_RaiseException]
  nop
.Lsecond_end:
  mov eax, -2
  jmp .Lepilogue
.Lcatch_second:
  mov rcx, rsp
  mov edx, 8
  call native_resume_step
  mov eax, DWORD PTR [rsp+64]
  mov DWORD PTR [rsp+36], eax
  lea rax, [rip+.Lresume_repeat]
  mov QWORD PTR [rsp+48], rax
  mov rcx, rsp
  mov edx, 2
  call native_resume_step
  xor ecx, ecx
  mov rdx, rsp
  call native_resume_cleanup
.Lrepeat_normal_suffix:
  mov rcx, rsp
  mov edx, 4
  call native_resume_step
.Lresume_repeat:
  mov rcx, rsp
  call native_resume_finish
  cmp DWORD PTR [rsp+44], 1370025985
  mov r10d, -1
  cmovne eax, r10d
.Lepilogue:
  add rsp, 96
  pop rbp
  ret
.seh_handlerdata
  .long 3
  .rva .Ltry_begin, .Ltry_end, native_resume_cleanup
  .long 0
  .rva .Ltry_begin, .Lnormal_call_end
  .rva native_resume_filter
  .rva .Lcatch_first
  .rva .Lsecond_begin, .Lsecond_end
  .rva native_resume_filter
  .rva .Lcatch_second
.text
.seh_endproc
